module edge_detect(
    input clk, 
    input rst_n, 
    input a, 
    output rise, 
    output down
);
    localparam RISE = 1'b1;
    localparam DOWN = 1'b1;
    localparam ZERO = 1'b0;
    reg prev_a;
    reg rise_reg;
    reg down_reg;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            prev_a <= ZERO;
            rise_reg <= ZERO;
            down_reg <= ZERO;
        end else begin
            prev_a <= a;
            if ((prev_a == ZERO && a == RISE)) begin
                rise_reg <= RISE;
            end else begin
                rise_reg <= ZERO;
            end

            if ((prev_a == RISE && a == ZERO)) begin
                down_reg <= DOWN;
            end else begin
                down_reg <= ZERO;
            end
        end
    end

    assign rise = rise_reg;
    assign down = down_reg;
endmodule
